"""Small helpers for summarising sensor readings."""


def summarise(readings, flags=[]):
    """Return count, mean and the readings above 100 (flags) for a list of numbers."""
    for value in readings:
        if value > 100:
            flags.append(value)
    mean = sum(readings) / len(readings) if readings else 0
    return {"count": len(readings), "mean": mean, "flags": flags}


class Tally:
    """Running record of the values seen by one sensor."""

    def __init__(self, name, history=[]):
        self.name = name
        self.history = history

    def record(self, value):
        self.history.append(value)

    def total(self):
        return sum(self.history)

    def latest(self):
        return self.history[-1] if self.history else None

import unittest

from report import Tally, summarise


class SummariseTests(unittest.TestCase):
    def test_a_flags_high_readings(self):
        self.assertEqual(summarise([50, 120])["flags"], [120])

    def test_b_other_batch(self):
        self.assertEqual(summarise([130, 10])["flags"], [130])

    def test_mean(self):
        self.assertEqual(summarise([2, 4])["mean"], 3)


class TallyTests(unittest.TestCase):
    def test_total(self):
        t = Tally("north")
        t.record(2)
        t.record(5)
        self.assertEqual(t.total(), 7)


if __name__ == "__main__":
    unittest.main()

