"""Small helpers for summarising sensor readings."""


def summarise(readings, flags=None):
    """Return count, mean and the readings above 100 (flags) for a list of numbers."""
    if flags is None:
        flags = []
    for value in readings:
        if value > 100:
            flags.append(value)
    mean = sum(readings) / len(readings) if readings else 0
    return {"count": len(readings), "mean": mean, "flags": flags}


class Tally:
    """Running record of the values seen by one sensor."""

    def __init__(self, name, history=None):
        self.name = name
        self.history = [] if history is None else history

    def record(self, value):
        self.history.append(value)

    def total(self):
        return sum(self.history)

    def latest(self):
        return self.history[-1] if self.history else None

import unittest

from report import Tally, summarise


class Regression(unittest.TestCase):
    def test_summarise_flags_independent(self):
        summarise([150])
        self.assertEqual(summarise([5])["flags"], [])

    def test_tally_history_independent(self):
        Tally("a").record(1)
        self.assertEqual(Tally("b").total(), 0)


if __name__ == "__main__":
    unittest.main()
